import SwiftUI
public struct ComedianDashboardView:View{public init(){};public var body:some View{NavigationStack{List{Section{HStack{VStack(alignment:.leading){Text("● 今すぐ通話受付").font(.headline).foregroundStyle(WaiwaiTheme.online);Text("受付中").font(.caption)};Spacer();Toggle("",isOn:.constant(true)).labelsHidden().tint(WaiwaiTheme.yellow)}}Section("今日"){Text("20:00 ビデオ通話　ファン：こんぺ")}Section("管理"){NavigationLink("プロフィール編集"){ComedianProfileEditView()};NavigationLink("PR・投稿管理"){ComedianVideoManagementView()};NavigationLink("スケジュール管理"){ComedianAvailabilityView()};NavigationLink("予約一覧"){ComedianReservationsView()};NavigationLink("レター・返信"){ComedianLetterReplyView()};NavigationLink("売上"){ComedianEarningsView()}}}.navigationTitle("芸人ホーム")}}}
public struct ComedianProfileEditView:View{@State var name="カベドンズ";@State var bio="大阪で活動中！しゃべくり漫才で勝負中。";public init(){};public var body:some View{Form{TextField("芸名 / コンビ名",text:$name);TextField("所属事務所",text:.constant("吉本興業"));TextField("ジャンル",text:.constant("漫才"));TextEditor(text:$bio).frame(height:100);Button("保存する"){}.buttonStyle(WaiwaiPrimaryButtonStyle())}.navigationTitle("プロフィール編集")}}
public struct ComedianVideoManagementView:View{public init(){};public var body:some View{ScrollView{VStack(alignment:.leading,spacing:18){Text("PR動画").font(.title2.bold());HStack{ForEach(1...3,id:\.self){i in RoundedRectangle(cornerRadius:14).fill(WaiwaiTheme.surface).frame(height:140).overlay(Text("PR \(i)"))}};Button("PR動画を入れ替える"){}.buttonStyle(WaiwaiPrimaryButtonStyle());Text("通常投稿 5 / 6").font(.title2.bold());LazyVGrid(columns:Array(repeating:GridItem(.flexible()),count:3)){ForEach(1...6,id:\.self){i in RoundedRectangle(cornerRadius:14).fill(WaiwaiTheme.surface).frame(height:116).overlay(Text(i==6 ? "＋ 新規投稿":"投稿 \(i)"))}}}.padding(20)}}}
public struct ComedianAvailabilityView:View{@State var instant=true;public init(){};public var body:some View{Form{DatePicker("日付",selection:.constant(Date()),displayedComponents:.date);DatePicker("開始",selection:.constant(Date()),displayedComponents:.hourAndMinute);DatePicker("終了",selection:.constant(Date().addingTimeInterval(7200)),displayedComponents:.hourAndMinute);Button("10分枠を公開する"){}.buttonStyle(WaiwaiPrimaryButtonStyle());Toggle("今すぐ通話受付",isOn:$instant).tint(WaiwaiTheme.yellow)}.navigationTitle("予約枠を設定")}}
public struct ComedianReservationsView:View{public init(){};public var body:some View{List{Text("今日 20:00　こんぺ　ビデオ通話");Text("9/25 18:20　ユーザーA　音声通話");Text("9/26 19:10　ユーザーB　ビデオ通話")}.navigationTitle("予約一覧")}}
public struct ComedianLetterReplyView:View{@State var reply="";public init(){};public var body:some View{Form{Section("こんぺ ・ 🔥最高 1,000円"){Text("いつも笑わせてもらってます！")};TextEditor(text:$reply).frame(height:120);Button("返信を送る"){}.buttonStyle(WaiwaiPrimaryButtonStyle())}.navigationTitle("レター・返信")}}
public struct ComedianEarningsView:View{public init(){};public var body:some View{List{Section{Text("今月の売上").font(.caption);Text("¥○○○,○○○").font(.largeTitle.bold())}Section("内訳"){LabeledContent("音声通話",value:"¥○○,○○○");LabeledContent("ビデオ通話",value:"¥○○,○○○");LabeledContent("レターギフト",value:"¥○○,○○○")}}.navigationTitle("売上")}}
